<script setup lang="ts">
import {ref,computed,onMounted,onUnmounted,nextTick} from 'vue';
import Icon from './Icon.vue';
import TaskExtras from './TaskExtras.vue';
type Project={id:number;name:string};type Item={text:string;done:boolean};type Task={id:number;title:string;description:string|null;project_id:number|null;status:string;priority:string;due_date:string|null;checklist:Item[]|null;sort_order:number;archived_at?:string|null;deleted_at?:string|null;project?:{id:number;name:string;archived_at:string|null}|null;labels?:{id:number;name:string;color:string}[];comments_count?:number;attachments_count?:number};
const user=ref<{name:string;email:string}|null>(null),projects=ref<Project[]>([]),tasks=ref<Task[]>([]),ready=ref(false),busy=ref(false),error=ref(''),csrf=ref('');
const register=ref(false),name=ref(''),email=ref(''),password=ref(''),confirmation=ref(''),view=ref('today'),query=ref(''),board=ref(false),project=ref<number|null>(null),draft=ref<Task|null>(null),newTitle=ref(''),newProject=ref<number|null>(null),newDate=ref(''),showAdd=ref(false),showProjects=ref(false),projectName=ref(''),subtext=ref(''),light=ref(false);
const lifecycle=ref<{archived_tasks:Task[];trashed_tasks:Task[];archived_projects:{id:number;name:string}[]}>({archived_tasks:[],trashed_tasks:[],archived_projects:[]}),statusFilter=ref('all');
const extrasDirty=ref(false),extrasBusy=ref(false);
const baseline=ref(''),saved=ref(false),decision=ref<{title:string;text:string;accept:string;action:()=>void}|null>(null);
const dirty=computed(()=>!!draft.value&&(snapshot(draft.value)!==baseline.value||!!subtext.value.trim()||extrasDirty.value));
function guard(action:()=>void){if(busy.value||extrasBusy.value)return;if(dirty.value){decision.value={title:'Есть несохранённые изменения',text:'Если продолжить, изменения в текущей задаче будут потеряны.',accept:'Не сохранять и продолжить',action};nextTick(()=>document.querySelector<HTMLButtonElement>('.decision-cancel')?.focus())}else action()}
function cancelDecision(){decision.value=null;nextTick(()=>document.querySelector<HTMLInputElement>('#task-title')?.focus())}
function acceptDecision(){const action=decision.value?.action;decision.value=null;action?.()}
function closeDetail(){guard(()=>{draft.value=null;subtext.value='';extrasDirty.value=false;})}
function beforeUnload(e:BeforeUnloadEvent){if(dirty.value){e.preventDefault();e.returnValue='';}}
function keyboard(e:KeyboardEvent){if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'&&draft.value&&!decision.value&&!showAdd.value){e.preventDefault();saveTask()}if(e.key==='Escape'&&!extrasDirty.value){if(decision.value)cancelDecision();else if(!showAdd.value&&!showProjects.value&&draft.value)closeDetail()}}
onMounted(()=>{window.addEventListener('beforeunload',beforeUnload);window.addEventListener('keydown',keyboard)});
onUnmounted(()=>{window.removeEventListener('beforeunload',beforeUnload);window.removeEventListener('keydown',keyboard)});
function today(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
const dateText=new Date().toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long'});
async function api(path:string,method='GET',body?:unknown){const r=await fetch(path,{method,headers:{Accept:'application/json','Content-Type':'application/json','X-CSRF-TOKEN':csrf.value},credentials:'same-origin',...(body===undefined?{}:{body:JSON.stringify(body)})});if(r.status===204)return null;const d=await r.json();if(!r.ok){if(r.status===401){user.value=null;tasks.value=[];projects.value=[]}throw Error(d.errors?Object.values(d.errors).flat().join(' '):r.status===419?'Сессия истекла. Обновите страницу.':d.message||'Не удалось выполнить запрос.')}return d}
async function run(fn:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'Ошибка соединения. Попробуйте ещё раз.'}finally{busy.value=false}}
async function load(){const d=await api('/data');projects.value=d.projects;tasks.value=d.tasks}
onMounted(async()=>{try{const s=await api('/session');csrf.value=s.csrf;user.value=s.user;if(user.value)await load()}catch{error.value='Не удалось подключиться к серверу.'}finally{ready.value=true}});
function auth(){run(async()=>{const d=await api(register.value?'/register':'/login','POST',{name:name.value,email:email.value.trim().toLowerCase(),password:password.value,password_confirmation:confirmation.value});user.value=d.user;csrf.value=d.csrf;password.value='';confirmation.value='';await load()})}
function logout(){guard(()=>performLogout())}
function performLogout(){run(async()=>{const s=await api('/logout','POST');csrf.value=s.csrf;user.value=null;tasks.value=[];projects.value=[];draft.value=null})}
const heading=computed(()=>view.value==='project'?projects.value.find(p=>p.id===project.value)?.name:({today:'Сегодня',inbox:'Входящие',upcoming:'Предстоящие',all:'Все задачи',archive:'Архив',trash:'Корзина'} as Record<string,string>)[view.value]);
const ordered=computed(()=>[...tasks.value].sort((a,b)=>(a.sort_order||0)-(b.sort_order||0)||a.id-b.id));
const visible=computed(()=>ordered.value.filter(t=>(view.value==='project'?t.project_id===project.value:view.value==='today'?t.due_date===today():view.value==='inbox'?!t.project_id:view.value==='upcoming'?(t.due_date||'')>today():true)&&(statusFilter.value==='all'||(statusFilter.value==='done'?t.status==='done':t.status!=='done'))&&(!query.value||(t.title+' '+(t.description||'')).toLowerCase().includes(query.value.toLowerCase()))));
function snapshot(t:Task){return JSON.stringify({id:t.id,title:t.title,description:t.description,project_id:t.project_id,status:t.status,priority:t.priority,due_date:t.due_date,checklist:t.checklist})}
function refreshSummary(t:Task){tasks.value=tasks.value.map(x=>x.id===t.id?t:x);if(draft.value?.id===t.id){draft.value.labels=t.labels;draft.value.comments_count=t.comments_count;draft.value.attachments_count=t.attachments_count}}
function openTask(t:Task){if(draft.value?.id!==t.id)extrasDirty.value=false;draft.value=JSON.parse(JSON.stringify({...t,checklist:t.checklist||[]}));baseline.value=snapshot(draft.value!);subtext.value='';saved.value=false;nextTick(()=>document.querySelector<HTMLInputElement>('#task-title')?.focus())}
function select(t:Task){if(draft.value?.id===t.id)return;guard(()=>openTask(t))}
function go(v:string,p:number|null=null){view.value=v;project.value=p;draft.value=null;subtext.value='';extrasDirty.value=false;showProjects.value=false}
function navigate(v:string,p:number|null=null){guard(()=>{if(v==='archive'||v==='trash')run(async()=>{lifecycle.value=await api('/lifecycle');go(v,p)});else go(v,p)})}
function startAdd(){guard(()=>{draft.value=null;subtext.value='';extrasDirty.value=false;showAdd.value=true;newDate.value=view.value==='today'?today():'';newProject.value=view.value==='project'?project.value:null;nextTick(()=>document.querySelector<HTMLInputElement>('#new-task-title')?.focus())})}
function addTask(){run(async()=>{const t=await api('/tasks','POST',{title:newTitle.value.trim(),project_id:newProject.value,due_date:newDate.value||null});tasks.value.push(t);showAdd.value=false;newTitle.value='';if(view.value==='archive'||view.value==='trash')go('all');openTask(t)})}
function createProject(){guard(()=>performCreateProject())}
function performCreateProject(){run(async()=>{const p=await api('/projects','POST',{name:projectName.value.trim()});projects.value.push(p);projectName.value='';go('project',p.id)})}
function saveTask(){if(!draft.value||busy.value||extrasBusy.value)return;if(!draft.value.title.trim()){error.value='Введите название задачи.';return;}addSub();run(async()=>{const t=await api('/tasks/'+draft.value!.id,'PATCH',draft.value);tasks.value=tasks.value.map(x=>x.id===t.id?t:x);openTask(t);saved.value=true})}
function toggle(t:Task){if(draft.value?.id===t.id&&dirty.value){guard(()=>performToggle(t))}else performToggle(t)}
function performToggle(t:Task){run(async()=>{const u=await api('/tasks/'+t.id,'PATCH',{status:t.status==='done'?'todo':'done'});tasks.value=tasks.value.map(x=>x.id===u.id?u:x);if(draft.value?.id===u.id)openTask(u)})}
function remove(){if(!draft.value||busy.value||extrasBusy.value)return;const id=draft.value.id;decision.value={title:'Переместить задачу в корзину?',text:'Задачу, чек-лист, файлы и комментарии можно будет восстановить из корзины.',accept:'В корзину',action:()=>{run(async()=>{await api('/tasks/'+id,'DELETE');tasks.value=tasks.value.filter(t=>t.id!==id);draft.value=null;subtext.value=''})}};nextTick(()=>document.querySelector<HTMLButtonElement>('.decision-cancel')?.focus())}
function archiveTask(){if(!draft.value)return;const id=draft.value.id;guard(()=>lifecycleAction('/tasks/'+id+'/archive'))}
function archiveProject(){if(project.value===null)return;const id=project.value;guard(()=>{decision.value={title:'Архивировать проект?',text:'Проект и его задачи будут скрыты с активной доски. Их можно вернуть из архива.',accept:'В архив',action:()=>lifecycleAction('/projects/'+id+'/archive',true)}})}
function lifecycleAction(path:string,leaveProject=false){run(async()=>{await api(path,'POST');draft.value=null;subtext.value='';extrasDirty.value=false;await load();if(leaveProject)go('today');if(view.value==='archive'||view.value==='trash')lifecycle.value=await api('/lifecycle')})}
const lifeTasks=computed(()=>(view.value==='trash'?lifecycle.value.trashed_tasks:lifecycle.value.archived_tasks).filter(t=>!query.value||t.title.toLowerCase().includes(query.value.toLowerCase())));
function addSub(){if(subtext.value.trim()&&draft.value){draft.value.checklist!.push({text:subtext.value.trim(),done:false});subtext.value=''}}
const dragging=ref<number|null>(null),dropStatus=ref(''),dropBefore=ref<number|null>(null),moving=ref(false);
function columnTasks(status:string){return visible.value.filter(t=>t.status===status)}
function clearDrag(){dragging.value=null;dropStatus.value='';dropBefore.value=null}
function dragStart(e:DragEvent,t:Task){if(busy.value||extrasBusy.value||dirty.value){e.preventDefault();if(dirty.value)error.value='Сохраните или закройте изменения задачи перед переносом.';return;}dragging.value=t.id;e.dataTransfer?.setData('text/plain',String(t.id));if(e.dataTransfer)e.dataTransfer.effectAllowed='move'}
function overColumn(e:DragEvent,status:string){if(!dragging.value)return;e.preventDefault();dropStatus.value=status;dropBefore.value=null}
function overCard(e:DragEvent,t:Task){if(!dragging.value||t.id===dragging.value)return;e.preventDefault();const rect=(e.currentTarget as HTMLElement).getBoundingClientRect();const rows=columnTasks(t.status).filter(x=>x.id!==dragging.value);const i=rows.findIndex(x=>x.id===t.id);dropStatus.value=t.status;dropBefore.value=e.clientY<rect.top+rect.height/2?t.id:(rows[i+1]?.id??null)}
function drop(){const id=dragging.value,status=dropStatus.value,before=dropBefore.value;clearDrag();if(id&&status)moveTask(id,status,before)}
function moveTask(id:number,status:string,before:number|null){guard(()=>{draft.value=null;subtext.value='';extrasDirty.value=false;moving.value=true;run(async()=>{try{const d=await api('/tasks/'+id+'/move','POST',{status,before_id:before});tasks.value=d.tasks}catch(e){error.value='Не удалось сохранить перенос. Положение карточек не изменено. '+(e instanceof Error?e.message:'');}finally{moving.value=false}})})}
function statusChange(e:Event,t:Task){const el=e.target as HTMLSelectElement;const status=el.value;el.value=t.status;moveTask(t.id,status,null)}
function stepTask(t:Task,direction:number){const rows=columnTasks(t.status);const i=rows.findIndex(x=>x.id===t.id);if(direction<0&&i>0)moveTask(t.id,t.status,rows[i-1].id);else if(direction>0&&i<rows.length-1)moveTask(t.id,t.status,rows[i+2]?.id??null)}
const columns=[{id:'todo',name:'К выполнению'},{id:'doing',name:'В работе'},{id:'done',name:'Готово'}];const pname=(id:number|null)=>projects.value.find(p=>p.id===id)?.name||'';
function decisionFocus(e:KeyboardEvent){if(e.key!=='Tab')return;const buttons=Array.from(document.querySelectorAll<HTMLButtonElement>('.decision-dialog button'));if(!buttons.length)return;const first=buttons[0],last=buttons[buttons.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}
</script>
<template>
<div :class="['shell',{light}]">
<div v-if="decision" class="overlay decision-overlay" @keydown="decisionFocus"><section class="modal decision-dialog" role="alertdialog" aria-modal="true" aria-labelledby="decision-title" aria-describedby="decision-text"><h2 id="decision-title">{{decision.title}}</h2><p id="decision-text" class="muted">{{decision.text}}</p><div class="actions"><button class="decision-cancel" @click="cancelDecision">Остаться</button><button class="primary" @click="acceptDecision">{{decision.accept}}</button></div></section></div>
 <div v-if="!ready" class="loading">◇ СовДело · Загрузка…</div>
 <main v-else-if="!user" class="auth"><div class="auth-brand">◇ <b>СовДело</b></div><p class="muted">Всё по делу. Вместе.</p><form @submit.prevent="auth"><h1>{{register?'Создать аккаунт':'С возвращением'}}</h1><p class="muted">Ваши проекты и задачи в одном месте</p><label v-if="register">Имя<input v-model="name" required maxlength="120" autocomplete="name"></label><label>Email<input v-model="email" type="email" required autocomplete="username"></label><label>Пароль<input v-model="password" type="password" required :minlength="register?10:undefined" maxlength="128" :autocomplete="register?'new-password':'current-password'"></label><label v-if="register">Повторите пароль<input v-model="confirmation" type="password" required autocomplete="new-password"></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary wide" :disabled="busy">{{busy?'Подождите…':register?'Зарегистрироваться':'Войти'}}</button><button type="button" class="link wide" @click="register=!register;error=''">{{register?'Уже есть аккаунт? Войти':'Нет аккаунта? Зарегистрироваться'}}</button></form><small class="muted">СовДело 0.1 · Локальный Laravel</small></main>
 <template v-else>
 <aside class="sidebar"><div class="brand">◇ <b>СовДело</b></div><nav><button v-for="n in [{v:'inbox',t:'Входящие',i:'inbox'},{v:'today',t:'Сегодня',i:'today'},{v:'upcoming',t:'Предстоящие',i:'upcoming'},{v:'all',t:'Все задачи',i:'all'},{v:'archive',t:'Архив',i:'archive'},{v:'trash',t:'Корзина',i:'trash'}]" :key="n.v" :class="{active:view===n.v}" @click="navigate(n.v)"><Icon :name="n.i"/>{{n.t}}</button></nav><p class="eyebrow">ПРОЕКТЫ</p><nav><button v-for="p in projects" :key="p.id" :class="{active:view==='project'&&project===p.id}" @click="navigate('project',p.id)"><Icon name="project"/> {{p.name}}</button></nav><form class="project-create" @submit.prevent="createProject"><input v-model="projectName" placeholder="Новый проект…" required maxlength="120" aria-label="Название проекта"><button :disabled="busy" aria-label="Создать проект">＋</button></form><div class="sidebar-bottom"><span class="muted">{{user.name}}</span><small>{{user.email}}</small><button class="link" @click="logout" :disabled="busy">Выйти</button><small>СовДело · 0.1</small></div></aside>
 <main class="workspace"><header><div><h1>{{heading}}</h1><p class="muted">{{dateText}}</p></div><div class="actions"><button aria-label="Переключить тему" @click="light=!light"><Icon name="theme"/></button><button class="primary" @click="startAdd" :disabled="busy">＋ Задача</button><span class="avatar">{{user.name.slice(0,1)}}</span><button class="mobile-logout" @click="logout">Выйти</button></div></header><p class="stage">ЛОКАЛЬНАЯ ВЕРСИЯ 0.1 <span>· Сохранение в PostgreSQL</span></p><div v-if="error" class="error" role="alert">{{error}} <button class="link" @click="error=''">Закрыть</button></div><p v-if="moving" class="save-status" role="status">Сохраняем положение карточки…</p><div class="toolbar"><input v-model="query" placeholder="Поиск задач…" aria-label="Поиск задач"><select v-if="view!=='archive'&&view!=='trash'" v-model="statusFilter" aria-label="Фильтр завершённых задач" class="status-filter"><option value="all">Все статусы</option><option value="open">Незавершённые</option><option value="done">Завершённые</option></select><button v-if="view==='project'" @click="archiveProject" :disabled="busy">В архив проект</button><button v-if="view!=='archive'&&view!=='trash'" @click="board=!board">{{board?'Список':'Доска'}}</button></div>
 <section v-if="view==='archive'||view==='trash'" class="lifecycle"><p class="muted">{{view==='trash'?'Задачи хранятся в корзине до восстановления. Автоматическая очистка пока отключена.':'Архивные задачи и проекты скрыты с активной доски.'}}</p><template v-if="view==='archive'"><h2 v-if="lifecycle.archived_projects.length">Проекты</h2><article v-for="p in lifecycle.archived_projects" :key="p.id" class="task"><Icon name="project"/><strong>{{p.name}}</strong><button class="restore-button" :disabled="busy" @click="lifecycleAction('/projects/'+p.id+'/restore')">Восстановить проект</button></article></template><h2>{{view==='trash'?'Удалённые задачи':'Задачи'}}</h2><article v-for="t in lifeTasks" :key="t.id" class="task"><div><strong>{{t.title}}</strong><div class="meta"><span v-if="t.project">{{t.project.name}}</span><span v-if="t.project?.archived_at">Проект в архиве</span><span v-if="t.attachments_count"><Icon name="attachment" :size="14"/> {{t.attachments_count}}</span><span v-if="t.comments_count"><Icon name="comment" :size="14"/> {{t.comments_count}}</span></div></div><button v-if="view==='trash'||!t.project?.archived_at" class="restore-button" :disabled="busy" @click="lifecycleAction('/tasks/'+t.id+'/restore')">Восстановить</button><small v-else class="restore-button">Сначала восстановите проект</small></article><p v-if="!lifeTasks.length" class="empty">Здесь пока пусто</p></section>
 <div v-else :class="['body',{editing:!!draft}]"><section class="task-area"><template v-if="!board"><h2>Задачи <span class="muted">· {{visible.length}}</span></h2><article v-for="t in visible" :key="t.id" :class="['task',{done:t.status==='done',selected:draft?.id===t.id}]" @click="select(t)" @keydown.enter.self="select(t)" tabindex="0" role="button" :aria-label="t.title"><button class="check" :disabled="busy" @click.stop="toggle(t)" :aria-label="t.status==='done'?'Вернуть задачу':'Завершить задачу'">{{t.status==='done'?'✓':''}}</button><div><strong>{{t.title}}</strong><div v-if="t.labels?.length" class="task-labels"><span v-for="l in t.labels" :key="l.id" :class="['label-badge',l.color]">{{l.name}}</span></div><div class="meta"><span v-if="t.attachments_count" title="Вложения"><Icon name="attachment" :size="14"/> {{t.attachments_count}}</span><span v-if="t.comments_count" title="Комментарии"><Icon name="comment" :size="14"/> {{t.comments_count}}</span><span v-if="t.project_id" class="tag">{{pname(t.project_id)}}</span><span v-if="t.due_date">{{t.due_date===today()?'Сегодня':t.due_date}}</span><span v-if="t.checklist?.length"><Icon name="checklist" :size="14"/> {{t.checklist.filter(x=>x.done).length}}/{{t.checklist.length}}</span></div></div><span v-if="t.priority==='high'" class="flag" aria-label="Высокий приоритет"><Icon name="flag"/></span></article></template>
 <div v-else class="board" :aria-busy="moving"><section v-for="c in columns" :key="c.id" :class="['column',{'drop-active':dropStatus===c.id}]" @dragover.self.prevent="overColumn($event,c.id)" @drop.prevent.stop="drop"><h2 @dragover.prevent="overColumn($event,c.id)">{{c.name}} · {{columnTasks(c.id).length}}</h2><template v-for="t in columnTasks(c.id)" :key="t.id"><div v-if="dropStatus===c.id&&dropBefore===t.id" class="drop-slot">Поместить сюда</div><article :class="['task','board-task',{dragging:dragging===t.id}]" :draggable="!busy&&!dirty" @dragstart="dragStart($event,t)" @dragend="clearDrag" @dragover.stop="overCard($event,t)" @drop.prevent.stop="drop"><button class="board-title" @click="select(t)">{{t.title}}</button><div v-if="t.labels?.length" class="task-labels"><span v-for="l in t.labels" :key="l.id" :class="['label-badge',l.color]">{{l.name}}</span></div><div class="meta"><span v-if="t.attachments_count" title="Вложения"><Icon name="attachment" :size="14"/> {{t.attachments_count}}</span><span v-if="t.comments_count" title="Комментарии"><Icon name="comment" :size="14"/> {{t.comments_count}}</span><span v-if="t.project_id" class="tag">{{pname(t.project_id)}}</span><span v-if="t.checklist?.length"><Icon name="checklist" :size="14"/> {{t.checklist.filter(x=>x.done).length}}/{{t.checklist.length}}</span></div><div class="board-controls"><button @click="stepTask(t,-1)" :disabled="busy||columnTasks(c.id)[0]?.id===t.id" aria-label="Поднять задачу">↑</button><button @click="stepTask(t,1)" :disabled="busy||columnTasks(c.id).at(-1)?.id===t.id" aria-label="Опустить задачу">↓</button><select :value="t.status" :disabled="busy" aria-label="Переместить задачу в статус" @change="statusChange($event,t)"><option v-for="dest in columns" :key="dest.id" :value="dest.id">{{dest.name}}</option></select></div></article></template><div v-if="dropStatus===c.id&&dropBefore===null" class="drop-slot" @dragover.prevent="overColumn($event,c.id)">Поместить в конец</div><div class="column-tail" @dragover.prevent="overColumn($event,c.id)" @drop.prevent.stop="drop">{{columnTasks(c.id).length?'Перетащите сюда':'Пустая колонка · перенесите задачу сюда'}}</div></section></div><div v-if="!visible.length" class="empty"><div>◇</div><h2>Здесь пока нет задач</h2><p>Добавьте задачу — и первое дело уже будет в плане.</p></div></section>
 <aside v-if="draft" class="detail"><div class="detail-head"><h2>Детали задачи</h2><button aria-label="Закрыть детали" @click="closeDetail" :disabled="busy">×</button></div><p class="save-status" role="status">{{busy?'Сохранение…':dirty?'● Есть несохранённые изменения':saved?'✓ Изменения сохранены':'Все изменения сохранены'}}</p><form @submit.prevent="saveTask"><fieldset :disabled="busy||extrasBusy"><label>Название<input id="task-title" v-model="draft.title" required maxlength="240"></label><label>Проект<select v-model="draft.project_id"><option :value="null">Без проекта</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><div class="two"><label>Статус<select v-model="draft.status"><option v-for="c in columns" :value="c.id" :key="c.id">{{c.name}}</option></select></label><label>Приоритет<select v-model="draft.priority"><option value="normal">Обычный</option><option value="high">Высокий</option></select></label></div><label>Срок<input v-model="draft.due_date" type="date"></label><label>Описание<textarea v-model="draft.description" rows="4" maxlength="20000"></textarea></label><label>Чек-лист</label><div v-for="(s,i) in draft.checklist" :key="i" class="sub"><input type="checkbox" v-model="s.done"><span>{{s.text}}</span><button type="button" @click="draft.checklist!.splice(i,1)" aria-label="Удалить пункт">×</button></div><div class="sub-add"><input v-model="subtext" placeholder="Новый пункт…" maxlength="500" @keydown.enter.prevent="addSub"><button type="button" @click="addSub">＋</button></div><button class="primary wide" :disabled="busy">{{busy?'Сохранение…':'Сохранить изменения'}}</button><p class="muted save-hint">Ctrl / ⌘ + S — сохранить</p><p v-if="error" class="error" role="alert">{{error}}</p><button type="button" class="wide" @click="archiveTask" :disabled="busy||extrasBusy">В архив</button><button type="button" class="link danger wide" @click="remove" :disabled="busy">В корзину</button></fieldset></form><TaskExtras :key="draft.id" :task-id="draft.id" :csrf="csrf" @updated="refreshSummary" @pending="extrasDirty=$event" @working="extrasBusy=$event"/></aside></div>
 </main>
 <nav class="mobile-nav"><button @click="navigate('today')"><Icon name="today"/><br>Сегодня</button><button @click="navigate('inbox')"><Icon name="inbox"/><br>Входящие</button><button @click="navigate('all')"><Icon name="all"/><br>Все задачи</button><button @click="showProjects=true"><Icon name="project"/><br>Проекты</button></nav>
 <div v-if="showAdd" class="overlay" @click.self="showAdd=false"><form class="modal" @submit.prevent="addTask"><h2>Новая задача</h2><label>Что нужно сделать?<input id="new-task-title" v-model="newTitle" required maxlength="240"></label><label>Проект<select v-model="newProject"><option :value="null">Без проекта</option><option v-for="p in projects" :key="p.id" :value="p.id">{{p.name}}</option></select></label><label>Срок<input type="date" v-model="newDate"></label><div class="actions"><button type="button" @click="showAdd=false">Отмена</button><button class="primary" :disabled="busy">Добавить</button></div><p v-if="error" class="error">{{error}}</p></form></div>
 <div v-if="showProjects" class="overlay" @click.self="showProjects=false"><div class="modal"><div class="detail-head"><h2>Проекты</h2><button @click="showProjects=false">×</button></div><button class="wide" style="margin-bottom:10px" @click="navigate('archive')">Архив</button><button class="wide" style="margin-bottom:10px" @click="navigate('trash')">Корзина</button><button v-for="p in projects" :key="p.id" class="wide" style="margin-bottom:10px" @click="navigate('project',p.id)">{{p.name}}</button><form @submit.prevent="createProject" class="sub-add"><input v-model="projectName" required maxlength="120" placeholder="Новый проект…"><button class="primary" :disabled="busy">＋</button></form></div></div>
 </template>
</div>
</template>
